mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "orderId": {
      "type": "string",
      "format": "uuid",
      "description": "Order identifier, as returned by list_exceptions."
    }
  },
  "required": [
    "orderId"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 50,
      "default": 20,
      "description": "Maximum number of orders to return."
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "orderId": {
      "type": "string",
      "format": "uuid",
      "description": "Order to correct."
    },
    "type": {
      "type": "string",
      "enum": [
        "RESTOCK",
        "REISSUE"
      ],
      "description": "RESTOCK to restock the missing quantity; REISSUE to reissue a rejected dispatch note."
    },
    "provider": {
      "type": "string",
      "enum": [
        "FAK",
        "ESC",
        "BOR"
      ],
      "description": "Provider for a RESTOCK. When omitted, the cheapest one of propose_alternatives."
    },
    "quantity": {
      "type": "integer",
      "minimum": 1,
      "description": "Units to restock. When omitted, the missing quantity."
    }
  },
  "required": [
    "orderId",
    "type"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "requestId": {
      "type": "string",
      "format": "uuid",
      "description": "Request identifier, as returned by request_correction."
    }
  },
  "required": [
    "requestId"
  ],
  "additionalProperties": false
}
